#[derive(Clone, Copy, Debug)]
enum SplPrs1Step {
    Start,
    OnTouch,
}

fn spl_prs1_run(ctx: &Ctx, mut step: SplPrs1Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            SplPrs1Step::Start => {
                step = SplPrs1Step::OnTouch;
                continue 'machine;
            }
            SplPrs1Step::OnTouch => {
                if (ctx.call(Function::IsEquipped, vec![Val::from(2782)])? == 1 && ctx.var("ep13_2_rhea").get()? == 100) {
                    ctx.lines_as(
                        "Voice from another side",
                        args![
                            "Sir, Please!!!",
                            "How can I communicate secretly with Manuk!!",
                            "I'm innocent. Please."
                        ],
                    )?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                } else {
                    ctx.lines_as(
                        "Voice from another side",
                        args!["RuffUdeneo Mu VilAsh", "YurReDur Ha DielTalNe Ko Lars", "HirVerWeh Yu AnuNud"],
                    )?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
            }
        }
    }
}

pub fn spl_prs1(ctx: &Ctx) -> Script {
    spl_prs1_run(ctx, SplPrs1Step::Start, Vec::new()).map(|_| ())
}

pub fn spl_prs1_ontouch(ctx: &Ctx) -> Script {
    spl_prs1_run(ctx, SplPrs1Step::OnTouch, Vec::new()).map(|_| ())
}

fn wandering_poet_ep13_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.call(Function::Cutin, vec![Val::from("god_nelluad02"), Val::from(2)])?;
    ctx.lines_as("Poet Nell", args!["Hi~~ do you hear the beautiful music coming from afar~?"])?;
    ctx.next()?;
    let choice = runtime::select_values(ctx, &[Val::from("Who are you?")])?;
    ctx.var("@menu").set(choice)?;
    ctx.call(Function::Cutin, vec![Val::from("god_nelluad01"), Val::from(2)])?;
    ctx.lines_as("Poet Nell", args!["Who, me...?", "I am just a poet enjoying the ambience..."])?;
    ctx.next()?;
    ctx.lines_as(
        "Poet Nell",
        args!["I cam here the other day, requesting to take notes of this new world and they allow me to follow the adventurers here."],
    )?;
    ctx.next()?;
    ctx.lines_as(
        "Poet Nell",
        args![
            "I became familiar with the Lapine.",
            "It was quite awkward at first... Since I didn't knew their language.",
            "But, one I started to play my instruments... they loved it."
        ],
    )?;
    ctx.next()?;
    ctx.lines_as(
        "Poet Nell",
        args![
            "They're fairies that know how to enjoy their lives..",
            "How happy they are...",
            "They are quite curious... I am honored to have met them..."
        ],
    )?;
    ctx.next()?;
    ctx.lines_as("Poet Nell", args!["So do you want to listen to my playing?"])?;
    ctx.next()?;
    'b1: {
        let subject1 = Val::from(runtime::select_values(ctx, &[Val::from("Sure.:Not really.")])?);
        let mut matched1 = false;
        let no_case1 = !subject1.loosely_equals(&Val::from(1)) && !subject1.loosely_equals(&Val::from(2));
        if !matched1 && subject1.loosely_equals(&Val::from(1)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as("Poet Nell", args!["What song do you want??"])?;
            ctx.next()?;
            'b2: {
                let subject2 = Val::from(runtime::select_values(
                    ctx,
                    &[Val::from("Poet of Bragie:Chaos in Eternity:Sunset Assassin:Ring of Nibelungen")],
                )?);
                let mut matched2 = false;
                let no_case2 = !subject2.loosely_equals(&Val::from(1))
                    && !subject2.loosely_equals(&Val::from(2))
                    && !subject2.loosely_equals(&Val::from(3))
                    && !subject2.loosely_equals(&Val::from(4));
                if !matched2 && subject2.loosely_equals(&Val::from(1)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.call(Function::Cutin, vec![Val::from("god_nelluad02"), Val::from(2)])?;
                    ctx.lines_as("Poet Nell", args!["Poet of Bragie!", "You must have a keen ear."])?;
                    ctx.call(Function::SoundEffect, vec![Val::from("bragis_poem.wav"), Val::from(0)])?;
                    break 'b2;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(2)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.call(Function::Cutin, vec![Val::from("god_nelluad02"), Val::from(2)])?;
                    ctx.lines_as(
                        "Poet Nell",
                        args![
                            "Chaos in Eternity...",
                            "This is a great piece but I wouldn't recommend it while dining..."
                        ],
                    )?;
                    ctx.call(Function::SoundEffect, vec![Val::from("chaos_of_eternity.wav"), Val::from(0)])?;
                    break 'b2;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(3)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.call(Function::Cutin, vec![Val::from("god_nelluad02"), Val::from(2)])?;
                    ctx.lines_as(
                        "Poet Nell",
                        args![
                            "Sunset Assassin!",
                            "Do you like Assassins?",
                            "This song tells of a legendary Assassin Cross that lived in the desert."
                        ],
                    )?;
                    ctx.call(Function::SoundEffect, vec![Val::from("assassin_of_sunset.wav"), Val::from(0)])?;
                    break 'b2;
                }
                if !matched2 && subject2.loosely_equals(&Val::from(4)) {
                    matched2 = true;
                }
                if matched2 {
                    ctx.call(Function::Cutin, vec![Val::from("god_nelluad02"), Val::from(2)])?;
                    ctx.lines_as(
                        "Poet Nell",
                        args!["Ring of Nibelungen...", "This song has quite an interesting story~"],
                    )?;
                    ctx.next()?;
                    ctx.call(Function::SoundEffect, vec![Val::from("ring_of_nibelungen.wav"), Val::from(0)])?;
                    ctx.lines(args![
                        "^4d4dff There was a river named Rhein that",
                        "that would shine as if made of gold.",
                        "It's secret hidden from all since",
                        "before this story was told...^000000"
                    ])?;
                    ctx.next()?;
                    ctx.lines(args![
                        "^4d4dff Valhalla was born from the goddess Freya.",
                        "The envious Rocky destroyed the goddess of beauty.^000000",
                        "^4d4dff Out of it's depths was born a ring made of fire.",
                        "A ring so strong it held the god's desires~^000000"
                    ])?;
                    ctx.next()?;
                    ctx.lines(args![
                        "^4d4dff Alberich's treasure now holds that power.",
                        "The power of the ring that held all the god's desires.^000000"
                    ])?;
                    ctx.next()?;
                    ctx.lines(args![
                        "^4d4dff The treasure was used to buy the world's soul.",
                        "A soul purchased with the weight of gold.^000000"
                    ])?;
                    ctx.next()?;
                    ctx.mes("^4d4dff Rocky afraid of losing control. transforms poor Alberich to the shape of a toad.")?;
                    ctx.next()?;
                    ctx.mes(
                        "^4d4dff Alberich swears with the last of his breath, that his treasured ring will curse it's wearer till death.",
                    )?;
                    ctx.next()?;
                    ctx.mes("^4d4dff Forever will the bearer be, cursed with Rocky's jealousy.")?;
                    break 'b2;
                }
            }
            break 'b1;
        }
        if !matched1 && subject1.loosely_equals(&Val::from(2)) {
            matched1 = true;
        }
        if matched1 {
            ctx.call(Function::Cutin, vec![Val::from("god_nelluad03"), Val::from(2)])?;
            ctx.lines_as(
                "Poet Nell",
                args![
                    "Why not?",
                    "Why would you stare at me like that if you didn't want to listen to my playing"
                ],
            )?;
            ctx.next()?;
            let choice = runtime::select_values(ctx, &[Val::from("You look like someone I know.")])?;
            ctx.var("@menu").set(choice)?;
            ctx.call(Function::Cutin, vec![Val::from("god_nelluad04"), Val::from(2)])?;
            ctx.lines_as("Poet Nell", args!["Eh?", "No way!", "Maybe you're confused..!"])?;
            ctx.next()?;
            ctx.lines_as(
                "Poet Nell",
                args!["Yes, I look quite common...", "But I doubt we've ever met before."],
            )?;
            ctx.next()?;
            ctx.call(Function::Cutin, vec![Val::from("god_nelluad01"), Val::from(255)])?;
            ctx.mes("- Nell seems embarrassed, then starts playing very complicated music -")?;
            break 'b1;
        }
    }
    ctx.close_window()?;
    ctx.call(Function::Cutin, vec![Val::from("god_nelluad01"), Val::from(255)])?;
    return Err(Stop::End);
}

